function activateMessagingPanel(name='contacts'){const view=$('view-whatsapp');if(!view)return;const selected=['contacts','whatsapp','system'].includes(name)?name:'contacts';view.querySelectorAll('[data-communication]').forEach(button=>button.classList.toggle('active',button.dataset.communication===selected));const contacts=$('communicationContacts'),whatsapp=$('communicationWhatsapp'),system=$('communicationSystem');if(contacts)contacts.hidden=selected!=='contacts';if(whatsapp)whatsapp.hidden=selected!=='whatsapp';if(system)system.hidden=selected!=='system';if(selected==='system')refreshSystemWhatsapp()}
function setupMailPage(){const gmail=$('communicationGmail'),mount=$('mailPageMount'),status=$('gmailStatus'),connection=$('mailConnectionMount');if(gmail&&mount){mount.append(gmail);gmail.hidden=false}if(status&&connection)connection.append(status);if($('openUnreadMail'))$('openUnreadMail').onclick=()=>{if($('gmailFolder').value!=='INBOX')$('gmailFolder').value='INBOX';$('gmailView').value='unread';loadMailbox()};if($('mailCheckNow'))$('mailCheckNow').onclick=async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Checking…';try{const result=await api('api/v1/intake/gmail/check',{method:'POST',body:'{}'});if(status)status.textContent=result.message;await loadMailboxFolders(true);await loadMailbox(true);await loadCommunications(false)}catch(error){if(status)status.textContent=error.message;toast(error.message)}finally{button.disabled=false;button.textContent='Check for new mail'}};if($('refreshMailConnections'))$('refreshMailConnections').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{await loadMailboxFolders(true);await loadMailbox(true);await loadCommunications(false,true)}finally{button.disabled=false}}}
function setupWhatsappPage(){const contacts=$('communicationContacts'),contactsMount=$('whatsappContactsMount'),whatsapp=$('communicationWhatsapp'),system=$('communicationSystem'),mount=$('whatsappPageMount');if(contacts&&contactsMount)contactsMount.append(contacts);if(whatsapp&&mount){mount.append(whatsapp);const compose=$('whatsappCompose'),sender=$('whatsappSenderPanel'),messageLog=whatsapp.querySelector('.compact-message-log');if(compose&&sender)whatsapp.insertBefore(compose,sender);if(compose&&messageLog)compose.after(messageLog)}if(system&&mount)mount.append(system);const view=$('view-whatsapp');if(view)view.querySelectorAll('[data-communication]').forEach(button=>button.onclick=()=>activateMessagingPanel(button.dataset.communication));activateMessagingPanel(view?.querySelector('[data-communication].active')?.dataset.communication||'contacts');if($('refreshSystemWhatsapp'))$('refreshSystemWhatsapp').onclick=()=>refreshSystemWhatsapp(true);if($('refreshWhatsappPage'))$('refreshWhatsappPage').onclick=async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Checking…';const ok=await loadCommunications(false,true);button.disabled=false;button.textContent='Check connections';showWhatsappConnectionResult(ok)};const form=$('whatsappAssistantSettings');if(form)form.onsubmit=async event=>{event.preventDefault();const button=event.submitter,data=new FormData(form),payload={reception_enabled:form.elements.reception_enabled.checked,manager_enabled:form.elements.manager_enabled.checked,unknown_reception:form.elements.unknown_reception.checked,trusted_ingestion:form.elements.trusted_ingestion.checked,reply_limit_unknown:Number(form.elements.reply_limit_unknown.value),reply_limit_manager:Number(form.elements.reply_limit_manager.value),voice:form.elements.voice.value,home_assistant_entities:data.getAll('home_assistant_entities'),home_assistant_camera_entities:data.getAll('home_assistant_camera_entities'),manager_controls:data.getAll('manager_controls')};button.disabled=true;try{const saved=await api('api/v1/communications/whatsapp/assistants',{method:'PUT',body:JSON.stringify(payload)});saved.home_assistant_device_catalog=state.communications.whatsapp.assistants.home_assistant_device_catalog||[];saved.home_assistant_camera_catalog=state.communications.whatsapp.assistants.home_assistant_camera_catalog||[];state.communications.whatsapp.assistants=saved;renderWhatsappAssistantSettings(saved);toast('WhatsApp assistants saved')}catch(error){toast(error.message)}finally{button.disabled=false}};const invite=$('whatsappAssistantInvite');if(invite)invite.onsubmit=event=>{event.preventDefault();sendWhatsappAssistantInvite(invite.elements.recipient.value,event.submitter)}}
async function loadWhatsappInviteLink(groupId){try{const result=await api(`api/v1/communications/whatsapp/groups/${encodeURIComponent(groupId)}/invite-link`),link=result.invite_link||result.link;if(!link)throw new Error('Meta has not produced an invite link yet');try{await navigator.clipboard.writeText(link);toast('Group invite link copied')}catch(_){prompt('Copy the WhatsApp group invite link',link)}}catch(error){toast(error.message)}}
async function loadMailboxFolders(refresh=false){try{const result=await api(`api/v1/communications/gmail/folders${refresh?'?refresh=true':''}`),select=$('gmailFolder'),current=select.value,icon={trash:'🗑 ',spam:'⚠ ',inbox:'✉ '},folders=result.folders||[];select.innerHTML=folders.map(folder=>`<option value="${esc(folder.name)}">${icon[folder.special]||''}${esc(folder.label)}</option>`).join('');if([...select.options].some(option=>option.value===current))select.value=current;const quick=$('gmailQuickFolders'),preferred=folders.filter(folder=>['inbox','spam','trash'].includes(folder.special));if(quick){quick.innerHTML=preferred.map(folder=>`<button type="button" data-mail-folder="${esc(folder.name)}" class="${folder.name===select.value?'active':''}">${icon[folder.special]||''}${esc(folder.label)}</button>`).join('');quick.querySelectorAll('[data-mail-folder]').forEach(button=>button.onclick=()=>{select.value=button.dataset.mailFolder;loadMailbox();quick.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button))})}}catch(error){toast(error.message)}}
function mailboxRow(row){const trash=/trash|cestino/i.test(row.folder),junk=/spam|junk|posta indesiderata/i.test(row.folder),when=row.sent_at?new Date(row.sent_at):null,size=row.size?`${Math.max(1,Math.round(row.size/1024))} KB`:'';return`<div class="mailbox-row ${row.unread?'unread':''}"><button class="mailbox-open" data-open-mail="${esc(row.uid)}" data-folder="${esc(row.folder)}"><span class="mail-avatar">${esc(String(row.sender_name||row.sender_address||'?').charAt(0).toUpperCase())}</span><span><span class="mail-sender-line"><b>${esc(row.sender_name||row.sender_address||'Unknown sender')}</b>${row.unread?'<em>New</em>':''}</span><small class="mail-address">${esc(row.sender_address||'')}</small><small class="mail-subject">${esc(row.subject||'(No subject)')}</small></span><time>${when?when.toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):''}<small>${size}</small></time></button><div class="mail-quick-actions">${trash?'<span class="mail-trash-state">Trash</span>':junk?'<span class="mail-trash-state">Junk</span>':`<button data-quick-mail="junk" data-mail-uid="${esc(row.uid)}" data-folder="${esc(row.folder)}" title="Move to Junk">⚠</button>`}${trash?'':`<button data-quick-mail="trash" data-mail-uid="${esc(row.uid)}" data-folder="${esc(row.folder)}" title="Move to Trash">🗑</button>`}</div></div>`}
async function quickMailAction(uid,folder,action,button){button.disabled=true;try{await api(`api/v1/communications/gmail/messages/${uid}`,{method:'PATCH',body:JSON.stringify({folder,action})});toast(action==='junk'?'Moved to Junk':'Moved to Trash · restore it from the Trash folder');await loadMailbox();await loadCommunications(false)}catch(error){toast(error.message);button.disabled=false}}
function renderMailboxSummary(result){const messages=result.messages||[],unread=Number(result.unread_total??messages.filter(item=>item.unread).length),starred=messages.filter(item=>item.starred).length,summary=$('mailInboxSummary'),banner=$('mailNewBanner'),note=$('mailInboxNote');if(summary)summary.innerHTML=`<article><span>Unread</span><strong>${unread}</strong></article><article><span>In folder</span><strong>${Number(result.total||messages.length)}</strong></article><article><span>Starred shown</span><strong>${starred}</strong></article>`;if(note)note.textContent=`${result.cached?'Fast cached view':'Live Gmail view'}${result.synced_at?` · synced ${timeLabel(result.synced_at)}`:''}`;if(banner){banner.hidden=!unread;if($('mailNewBannerNote'))$('mailNewBannerNote').textContent=`${unread} unread message${unread===1?'':'s'} in this folder`}}
async function loadMailbox(refresh=false){const node=$('gmailMailbox');if(!node)return;if(!state.mailbox)node.textContent='Loading cached mailbox…';try{const result=await api(`api/v1/communications/gmail/messages?folder=${encodeURIComponent($('gmailFolder').value)}&view=${encodeURIComponent($('gmailView').value)}&limit=60${refresh?'&refresh=true':''}`);state.mailbox=result;renderMailboxSummary(result);node.classList.toggle('empty',!result.messages.length);const cacheNote=result.cached&&result.synced_at?`<div class="mail-cache-note">Cached mailbox · synced ${esc(timeLabel(result.synced_at))}</div>`:'';node.innerHTML=cacheNote+(result.messages.length?result.messages.map(mailboxRow).join(''):'No messages in this view.');node.querySelectorAll('[data-open-mail]').forEach(button=>button.onclick=()=>openMail(button.dataset.openMail,button.dataset.folder));node.querySelectorAll('[data-quick-mail]').forEach(button=>button.onclick=()=>quickMailAction(button.dataset.mailUid,button.dataset.folder,button.dataset.quickMail,button))}catch(error){node.classList.add('empty');node.textContent=error.message}}
async function openMail(uid,folder){try{const item=await api(`api/v1/communications/gmail/messages/${uid}?folder=${encodeURIComponent(folder)}`);state.openMail={uid,folder,item};$('mailDialogTitle').textContent=item.subject;$('mailDetail').innerHTML=`<div class="mail-metadata"><div class="mail-avatar large">${esc(String(item.sender_name||item.sender_address||'?').charAt(0).toUpperCase())}</div><dl><div><dt>From</dt><dd><b>${esc(item.sender_name||item.sender_address)}</b> &lt;${esc(item.sender_address)}&gt;</dd></div><div><dt>To</dt><dd>${esc(item.to||'—')}</dd></div>${item.cc?`<div><dt>Cc</dt><dd>${esc(item.cc)}</dd></div>`:''}<div><dt>Received</dt><dd>${esc(item.date||'—')}</dd></div><div><dt>Folder</dt><dd>${esc(folder)}</dd></div></dl></div><div class="mail-body">${esc(item.body||'(No readable message body)')}</div>${item.attachments.length?`<div class="mail-attachments"><h4>Attachments</h4>${item.attachments.map(file=>`<a class="button-link" href="api/v1/communications/gmail/messages/${uid}/attachments/${file.index}?folder=${encodeURIComponent(folder)}">↓ ${esc(file.filename)} <small>${esc(file.content_type)} · ${Math.max(1,Math.round(file.size/1024))} KB</small></a>`).join('')}</div>`:''}`;$('downloadMail').href=`api/v1/communications/gmail/messages/${uid}/download?folder=${encodeURIComponent(folder)}`;const trash=/trash|cestino/i.test(folder),junk=/spam|junk|posta indesiderata/i.test(folder);document.querySelector('[data-mail-action="restore"]').hidden=!(trash||junk);document.querySelector('[data-mail-action="trash"]').hidden=trash;document.querySelector('[data-mail-action="junk"]').hidden=trash||junk;document.querySelector('[data-mail-action="delete"]').hidden=!trash;const status=$('mailActionStatus');status.hidden=true;status.textContent='';$('mailDialog').showModal();await loadMailbox()}catch(error){toast(error.message)}}
function composeFromMail(mode){const item=state.openMail?.item,form=$('gmailCompose');if(!item||!form)return;$('mailDialog').close();form.elements.recipients.value=mode==='reply'?item.sender_address:'';form.elements.subject.value=(mode==='reply'?'Re: ':'Fwd: ')+String(item.subject||'').replace(/^(re|fwd):\s*/i,'');form.elements.body.value=`\n\n--- ${mode==='reply'?'Original message':'Forwarded message'} ---\nFrom: ${item.sender_name||item.sender_address} <${item.sender_address}>\nDate: ${item.date||''}\n\n${item.body||''}`;form.scrollIntoView({behavior:'smooth',block:'center'});form.elements.body.focus()}
async function mailAction(action,button){if(!state.openMail)return;if(action==='delete'&&!confirm('Permanently delete this email? This cannot be undone.'))return;const status=$('mailActionStatus'),label=button?.textContent||action;if(button)button.disabled=true;status.hidden=false;status.className='mail-action-status working';status.textContent=`${label}…`;try{await api(`api/v1/communications/gmail/messages/${state.openMail.uid}`,{method:'PATCH',body:JSON.stringify({folder:state.openMail.folder,action})});const notice={unread:'Marked unread',star:'Starred',unstar:'Star removed',archive:'Archived',trash:'Moved to Trash · it can be restored',junk:'Moved to Junk',restore:'Restored to Inbox',delete:'Email permanently deleted'}[action]||`Email ${action} updated`;status.className='mail-action-status success';status.textContent=`✓ ${notice}`;if(['archive','trash','junk','restore','delete'].includes(action))setTimeout(()=>{if($('mailDialog').open)$('mailDialog').close()},450);await loadMailbox();await loadCommunications(false)}catch(error){status.className='mail-action-status error';status.textContent=`! ${error.message}`}finally{if(button)button.disabled=false}}
async function loadCommunications(withMailbox=true,refresh=false){try{state.communications=await api(`api/v1/communications${refresh?'?refresh=true':''}`);renderCommunications();setupMailPage();setupWhatsappPage();if(withMailbox&&state.communications.gmail?.status?.configured){await loadMailboxFolders();await loadMailbox()}return true}catch(error){toast(error.message);return false}}
